-- load_dw.sql
-- Loads data from STAGING to DW using SCD Type 2 for dimensions and upsert MERGE for fact tables.
USE DATABASE ADVENTUREWORKS_MIGRATED;
USE SCHEMA DW;

SELECT 'Starting DW load from STAGING schema' AS status;

SELECT 'Applying SCD Type 2 for DW.dim_account from STAGING.dim_account_stg' AS status;
MERGE INTO ADVENTUREWORKS_MIGRATED.DW.dim_account AS tgt
USING (
  SELECT src.*, SHA2(CONCAT_WS('||', COALESCE(TO_VARCHAR(src."PARENTACCOUNTKEY"), '__NULL__'), COALESCE(TO_VARCHAR(src."ACCOUNTCODEALTERNATEKEY"), '__NULL__'), COALESCE(TO_VARCHAR(src."PARENTACCOUNTCODEALTERNATEKEY"), '__NULL__'), COALESCE(TO_VARCHAR(src."ACCOUNTDESCRIPTION"), '__NULL__'), COALESCE(TO_VARCHAR(src."ACCOUNTTYPE"), '__NULL__'), COALESCE(TO_VARCHAR(src."OPERATOR"), '__NULL__'), COALESCE(TO_VARCHAR(src."CUSTOMMEMBERS"), '__NULL__'), COALESCE(TO_VARCHAR(src."VALUETYPE"), '__NULL__'), COALESCE(TO_VARCHAR(src."CUSTOMMEMBEROPTIONS"), '__NULL__')), 256) AS src_hash
  FROM ADVENTUREWORKS_MIGRATED.STAGING.dim_account_stg AS src
) AS src
ON tgt."ACCOUNTKEY" = src."ACCOUNTKEY"
  AND tgt."_IS_CURRENT" = TRUE
WHEN MATCHED AND (SHA2(CONCAT_WS('||', COALESCE(TO_VARCHAR(tgt."PARENTACCOUNTKEY"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."ACCOUNTCODEALTERNATEKEY"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."PARENTACCOUNTCODEALTERNATEKEY"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."ACCOUNTDESCRIPTION"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."ACCOUNTTYPE"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."OPERATOR"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."CUSTOMMEMBERS"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."VALUETYPE"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."CUSTOMMEMBEROPTIONS"), '__NULL__')), 256) <> src.src_hash) THEN
  UPDATE SET tgt."_IS_CURRENT" = FALSE, tgt."_VALID_TO" = CURRENT_TIMESTAMP();

MERGE INTO ADVENTUREWORKS_MIGRATED.DW.dim_account AS tgt
USING (
  SELECT src.*, SHA2(CONCAT_WS('||', COALESCE(TO_VARCHAR(src."PARENTACCOUNTKEY"), '__NULL__'), COALESCE(TO_VARCHAR(src."ACCOUNTCODEALTERNATEKEY"), '__NULL__'), COALESCE(TO_VARCHAR(src."PARENTACCOUNTCODEALTERNATEKEY"), '__NULL__'), COALESCE(TO_VARCHAR(src."ACCOUNTDESCRIPTION"), '__NULL__'), COALESCE(TO_VARCHAR(src."ACCOUNTTYPE"), '__NULL__'), COALESCE(TO_VARCHAR(src."OPERATOR"), '__NULL__'), COALESCE(TO_VARCHAR(src."CUSTOMMEMBERS"), '__NULL__'), COALESCE(TO_VARCHAR(src."VALUETYPE"), '__NULL__'), COALESCE(TO_VARCHAR(src."CUSTOMMEMBEROPTIONS"), '__NULL__')), 256) AS src_hash
  FROM ADVENTUREWORKS_MIGRATED.STAGING.dim_account_stg AS src
) AS src
ON tgt."ACCOUNTKEY" = src."ACCOUNTKEY"
  AND tgt."_IS_CURRENT" = TRUE
  AND (SHA2(CONCAT_WS('||', COALESCE(TO_VARCHAR(tgt."PARENTACCOUNTKEY"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."ACCOUNTCODEALTERNATEKEY"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."PARENTACCOUNTCODEALTERNATEKEY"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."ACCOUNTDESCRIPTION"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."ACCOUNTTYPE"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."OPERATOR"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."CUSTOMMEMBERS"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."VALUETYPE"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."CUSTOMMEMBEROPTIONS"), '__NULL__')), 256) = src.src_hash)
WHEN NOT MATCHED THEN
  INSERT ("ACCOUNTKEY", "PARENTACCOUNTKEY", "ACCOUNTCODEALTERNATEKEY", "PARENTACCOUNTCODEALTERNATEKEY", "ACCOUNTDESCRIPTION", "ACCOUNTTYPE", "OPERATOR", "CUSTOMMEMBERS", "VALUETYPE", "CUSTOMMEMBEROPTIONS", "_VALID_FROM", "_VALID_TO", "_IS_CURRENT")
  VALUES (src."ACCOUNTKEY", src."PARENTACCOUNTKEY", src."ACCOUNTCODEALTERNATEKEY", src."PARENTACCOUNTCODEALTERNATEKEY", src."ACCOUNTDESCRIPTION", src."ACCOUNTTYPE", src."OPERATOR", src."CUSTOMMEMBERS", src."VALUETYPE", src."CUSTOMMEMBEROPTIONS", CURRENT_TIMESTAMP(), NULL, TRUE);

SELECT 'Applying SCD Type 2 for DW.dim_currency from STAGING.dim_currency_stg' AS status;
MERGE INTO ADVENTUREWORKS_MIGRATED.DW.dim_currency AS tgt
USING (
  SELECT src.*, SHA2(CONCAT_WS('||', COALESCE(TO_VARCHAR(src."CURRENCYALTERNATEKEY"), '__NULL__'), COALESCE(TO_VARCHAR(src."CURRENCYNAME"), '__NULL__')), 256) AS src_hash
  FROM ADVENTUREWORKS_MIGRATED.STAGING.dim_currency_stg AS src
) AS src
ON tgt."CURRENCYKEY" = src."CURRENCYKEY"
  AND tgt."_IS_CURRENT" = TRUE
WHEN MATCHED AND (SHA2(CONCAT_WS('||', COALESCE(TO_VARCHAR(tgt."CURRENCYALTERNATEKEY"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."CURRENCYNAME"), '__NULL__')), 256) <> src.src_hash) THEN
  UPDATE SET tgt."_IS_CURRENT" = FALSE, tgt."_VALID_TO" = CURRENT_TIMESTAMP();

MERGE INTO ADVENTUREWORKS_MIGRATED.DW.dim_currency AS tgt
USING (
  SELECT src.*, SHA2(CONCAT_WS('||', COALESCE(TO_VARCHAR(src."CURRENCYALTERNATEKEY"), '__NULL__'), COALESCE(TO_VARCHAR(src."CURRENCYNAME"), '__NULL__')), 256) AS src_hash
  FROM ADVENTUREWORKS_MIGRATED.STAGING.dim_currency_stg AS src
) AS src
ON tgt."CURRENCYKEY" = src."CURRENCYKEY"
  AND tgt."_IS_CURRENT" = TRUE
  AND (SHA2(CONCAT_WS('||', COALESCE(TO_VARCHAR(tgt."CURRENCYALTERNATEKEY"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."CURRENCYNAME"), '__NULL__')), 256) = src.src_hash)
WHEN NOT MATCHED THEN
  INSERT ("CURRENCYKEY", "CURRENCYALTERNATEKEY", "CURRENCYNAME", "_VALID_FROM", "_VALID_TO", "_IS_CURRENT")
  VALUES (src."CURRENCYKEY", src."CURRENCYALTERNATEKEY", src."CURRENCYNAME", CURRENT_TIMESTAMP(), NULL, TRUE);

SELECT 'Applying SCD Type 2 for DW.dim_customer from STAGING.dim_customer_stg' AS status;
MERGE INTO ADVENTUREWORKS_MIGRATED.DW.dim_customer AS tgt
USING (
  SELECT src.*, SHA2(CONCAT_WS('||', COALESCE(TO_VARCHAR(src."GEOGRAPHYKEY"), '__NULL__'), COALESCE(TO_VARCHAR(src."CUSTOMERALTERNATEKEY"), '__NULL__'), COALESCE(TO_VARCHAR(src."TITLE"), '__NULL__'), COALESCE(TO_VARCHAR(src."FIRSTNAME"), '__NULL__'), COALESCE(TO_VARCHAR(src."MIDDLENAME"), '__NULL__'), COALESCE(TO_VARCHAR(src."LASTNAME"), '__NULL__'), COALESCE(TO_VARCHAR(src."NAMESTYLE"), '__NULL__'), COALESCE(TO_VARCHAR(src."BIRTHDATE"), '__NULL__'), COALESCE(TO_VARCHAR(src."MARITALSTATUS"), '__NULL__'), COALESCE(TO_VARCHAR(src."SUFFIX"), '__NULL__'), COALESCE(TO_VARCHAR(src."GENDER"), '__NULL__'), COALESCE(TO_VARCHAR(src."EMAILADDRESS"), '__NULL__'), COALESCE(TO_VARCHAR(src."YEARLYINCOME"), '__NULL__'), COALESCE(TO_VARCHAR(src."TOTALCHILDREN"), '__NULL__'), COALESCE(TO_VARCHAR(src."NUMBERCHILDRENATHOME"), '__NULL__'), COALESCE(TO_VARCHAR(src."ENGLISHEDUCATION"), '__NULL__'), COALESCE(TO_VARCHAR(src."SPANISHEDUCATION"), '__NULL__'), COALESCE(TO_VARCHAR(src."FRENCHEDUCATION"), '__NULL__'), COALESCE(TO_VARCHAR(src."ENGLISHOCCUPATION"), '__NULL__'), COALESCE(TO_VARCHAR(src."SPANISHOCCUPATION"), '__NULL__'), COALESCE(TO_VARCHAR(src."FRENCHOCCUPATION"), '__NULL__'), COALESCE(TO_VARCHAR(src."HOUSEOWNERFLAG"), '__NULL__'), COALESCE(TO_VARCHAR(src."NUMBERCARSOWNED"), '__NULL__'), COALESCE(TO_VARCHAR(src."ADDRESSLINE1"), '__NULL__'), COALESCE(TO_VARCHAR(src."ADDRESSLINE2"), '__NULL__'), COALESCE(TO_VARCHAR(src."PHONE"), '__NULL__'), COALESCE(TO_VARCHAR(src."DATEFIRSTPURCHASE"), '__NULL__'), COALESCE(TO_VARCHAR(src."COMMUTEDISTANCE"), '__NULL__')), 256) AS src_hash
