USING (
  SELECT src.*, SHA2(CONCAT_WS('||', COALESCE(TO_VARCHAR(src."FULLDATEALTERNATEKEY"), '__NULL__'), COALESCE(TO_VARCHAR(src."DAYNUMBEROFWEEK"), '__NULL__'), COALESCE(TO_VARCHAR(src."ENGLISHDAYNAMEOFWEEK"), '__NULL__'), COALESCE(TO_VARCHAR(src."SPANISHDAYNAMEOFWEEK"), '__NULL__'), COALESCE(TO_VARCHAR(src."FRENCHDAYNAMEOFWEEK"), '__NULL__'), COALESCE(TO_VARCHAR(src."DAYNUMBEROFMONTH"), '__NULL__'), COALESCE(TO_VARCHAR(src."DAYNUMBEROFYEAR"), '__NULL__'), COALESCE(TO_VARCHAR(src."WEEKNUMBEROFYEAR"), '__NULL__'), COALESCE(TO_VARCHAR(src."ENGLISHMONTHNAME"), '__NULL__'), COALESCE(TO_VARCHAR(src."SPANISHMONTHNAME"), '__NULL__'), COALESCE(TO_VARCHAR(src."FRENCHMONTHNAME"), '__NULL__'), COALESCE(TO_VARCHAR(src."MONTHNUMBEROFYEAR"), '__NULL__'), COALESCE(TO_VARCHAR(src."CALENDARQUARTER"), '__NULL__'), COALESCE(TO_VARCHAR(src."CALENDARYEAR"), '__NULL__'), COALESCE(TO_VARCHAR(src."CALENDARSEMESTER"), '__NULL__'), COALESCE(TO_VARCHAR(src."FISCALQUARTER"), '__NULL__'), COALESCE(TO_VARCHAR(src."FISCALYEAR"), '__NULL__'), COALESCE(TO_VARCHAR(src."FISCALSEMESTER"), '__NULL__')), 256) AS src_hash
