WHEN MATCHED AND (SHA2(CONCAT_WS('||', COALESCE(TO_VARCHAR(tgt."FULLDATEALTERNATEKEY"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."DAYNUMBEROFWEEK"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."ENGLISHDAYNAMEOFWEEK"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."SPANISHDAYNAMEOFWEEK"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."FRENCHDAYNAMEOFWEEK"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."DAYNUMBEROFMONTH"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."DAYNUMBEROFYEAR"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."WEEKNUMBEROFYEAR"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."ENGLISHMONTHNAME"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."SPANISHMONTHNAME"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."FRENCHMONTHNAME"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."MONTHNUMBEROFYEAR"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."CALENDARQUARTER"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."CALENDARYEAR"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."CALENDARSEMESTER"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."FISCALQUARTER"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."FISCALYEAR"), '__NULL__'), COALESCE(TO_VARCHAR(tgt."FISCALSEMESTER"), '__NULL__')), 256) <> src.src_hash) THEN
