ON tgt."CURRENCYID" = src."CURRENCYID" AND tgt."CURRENCYDATE" = src."CURRENCYDATE"
WHEN MATCHED THEN UPDATE SET tgt."AVERAGERATE" = src."AVERAGERATE", tgt."ENDOFDAYRATE" = src."ENDOFDAYRATE", tgt."CURRENCYKEY" = src."CURRENCYKEY", tgt."DATEKEY" = src."DATEKEY"
WHEN NOT MATCHED THEN
  INSERT ("AVERAGERATE", "CURRENCYID", "CURRENCYDATE", "ENDOFDAYRATE", "CURRENCYKEY", "DATEKEY")
  VALUES (src."AVERAGERATE", src."CURRENCYID", src."CURRENCYDATE", src."ENDOFDAYRATE", src."CURRENCYKEY", src."DATEKEY");

